test("nested pools scenario 3", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "3.00");
  await ui.setSetting(pg_uma, "late-pct", "10.00");
  await ui.setSetting(pg_uma, "terms-A", "3");
  await ui.setSetting(pg_uma, "cap", "2.00");
  await ui.setSetting(pg_uma, "proof-threshold", "1.00");
  await ui.setSetting(pg_uma, "grace-days", "3");
  expect(await ui.addHoliday(pg_uma, "2026-03-13")).toBe(true);
  expect(await ui.addHoliday(pg_uma, "2026-03-24")).toBe(true);
  expect(await ui.addVoidReason(pg_uma, "dup")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "33.33", "from": "2026-03-01", "to": "2026-03-12"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C", "terms": "20"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B", "terms": "20"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A", "terms": "3", "contact": "ben@x"}));
  expect(await ui.addPool(pg_uma, "P1")).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Cam", "share": "50.00"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ada", "share": "50.00"})).toBe(true);
  expect(await ui.addPool(pg_uma, "P2")).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P2", {"member": "Cam", "share": "100.00"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "pool:P2", "share": "10.00"})).toBe(true);
  expect(await ui.addPatron(pg_uma, p_cam, "Ada")).toBe(true);
  await ui.setSetting(pg_uma, "policy-date", "2026-03-05");
  expect(await ui.addHoliday(pg_uma, "2026-03-27")).toBe(true);
  const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "3.33", "note": "n", "ref": "inv 7"}));
  expect(await ui.retire(pg_uma, p_ben, "2026-04-02")).toBe(true);
  expect(await ui.periodAction(pg_uma, "P2", "soft-close")).toBe(true);
  await ui.showRetired(pg_uma, true);
  expect(await ui.statementAsOf(pg_uma, p_ben, "2026-03-05")).toBe(false);
  await ui.refresh(pg_uma);
  expect(await ui.statement(pg_uma, p_ada)).toBe(true);
  const c_ben_1 = ui.must(await ui.addClaimTwice(pg_uma, p_ben, {"amount": "4.00", "date": "2026-03-05"}));
  expect(await ui.claimCount(pg_uma, p_ben)).toBe(2);
  expect(await ui.editPerson(pg_uma, p_ada, {"grade": "B", "gradeFrom": "2026-03-28"})).toBe(true);
  expect(await ui.claimAction(pg_uma, c_ben_1, "open")).toBe(true);
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  await ui.showRetired(pg_vic, true);
  expect(await ui.bulkReassign(pg_vic, [c_ben_0, c_ben_1], "Cam")).toEqual({ reassigned: 2, refused: 0 });
  expect(await ui.hold(pg_vic, p_ben, {"from": "2026-02-10"})).toBe(true);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  await ui.refresh(pg_wes);
  await expect(pg_wes.getByTestId("person-row-" + p_ben)).toHaveCount(0);

